"use client";

import { useEffect, useRef, useState } from "react";

export function SnapSectionsTailwind() {
  const ref = useRef(null);
  const [active, setActive] = useState(0);
  const sections = ["Capture", "Organize", "Collaborate", "Publish"];
  const go = (i) => {
    const el = ref.current;
    const next = Math.max(0, Math.min(sections.length - 1, i));
    setActive(next);
    el.scrollTo({ top: next * el.clientHeight, behavior: "smooth" });
  };
  useEffect(() => {
    const el = ref.current;
    let last = 0;
    const onWheel = (e) => {
      const now = performance.now();
      const fresh = now - last > 160;
      last = now;
      const idx = Math.round(el.scrollTop / el.clientHeight);
      if ((e.deltaY < 0 && idx === 0) || (e.deltaY > 0 && idx === sections.length - 1)) return;
      e.preventDefault();
      if (fresh) go(idx + Math.sign(e.deltaY));
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);
  return (
    <div className="relative h-[380px] w-full overflow-hidden rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div ref={ref} tabIndex={0} className="h-full snap-y snap-mandatory overflow-y-auto">
        {sections.map((t, i) => (
          <section key={t} className="flex h-full snap-start items-center px-16">
            <div>
              <span className="font-mono text-xs text-emerald-400">0{i + 1} / 0{sections.length}</span>
              <h3 className="text-5xl font-bold tracking-tight">{t}</h3>
            </div>
          </section>
        ))}
      </div>
      <nav className="absolute right-4 top-1/2 flex -translate-y-1/2 flex-col gap-2">
        {sections.map((t, i) => (
          <button key={t} aria-label={`Go to ${t}`} onClick={() => go(i)} className={`w-2 rounded-full transition-all ${i === active ? "h-5 bg-emerald-400" : "h-2 bg-zinc-600"}`} />
        ))}
      </nav>
    </div>
  );
}
